import { Book, ApiResponse } from '../types/book';

// Dữ liệu sách giả lập ban đầu
const INITIAL_BOOKS: Book[] = [
  {
    id: 'b1',
    title: 'Lập trình TypeScript toàn diện',
    author: 'Nguyễn Văn A',
    category: 'CNTT',
    publishedYear: 2023,
    availableCopies: 3,
  },
  {
    id: 'b2',
    title: 'Cấu trúc dữ liệu và giải thuật',
    author: 'Trần Thị B',
    category: 'CNTT',
    publishedYear: 2021,
    availableCopies: 1,
  },
  {
    id: 'b3',
    title: 'Kinh tế vi mô nhập môn',
    author: 'Lê Hoàng C',
    category: 'Kinh tế',
    publishedYear: 2022,
    availableCopies: 2,
  },
  {
    id: 'b4',
    title: 'Nguyên lý Marketing căn bản',
    author: 'Phạm Minh D',
    category: 'Kinh tế',
    publishedYear: 2020,
    availableCopies: 0, // Hết sách để kiểm tra nút Mượn bị disabled
  },
  {
    id: 'b5',
    title: 'English for IT Specialists',
    author: 'David Evans',
    category: 'Ngoại ngữ',
    publishedYear: 2022,
    availableCopies: 4,
  },
  {
    id: 'b6',
    title: 'Luyện thi IELTS - Kỹ năng đọc hiểu',
    author: 'Hoàng Kim E',
    category: 'Ngoại ngữ',
    publishedYear: 2024,
    availableCopies: 2,
  },
  {
    id: 'b7',
    title: 'Kiến trúc phần mềm Clean Architecture',
    author: 'Robert C. Martin',
    category: 'CNTT',
    publishedYear: 2019,
    availableCopies: 2,
  },
  {
    id: 'b8',
    title: 'Tài chính doanh nghiệp thực hành',
    author: 'Đỗ Thị F',
    category: 'Kinh tế',
    publishedYear: 2023,
    availableCopies: 1,
  },
];

/**
 * Mock API lấy danh sách sách từ server giả lập.
 * Độ trễ: 500ms
 * Trả về kiểu Generic ApiResponse<Book[]>
 * @param shouldFail Nếu truyền true, API sẽ giả lập lỗi kết nối
 */
export const fetchBooksApi = (
  shouldFail: boolean = false
): Promise<ApiResponse<Book[]>> => {
  return new Promise((resolve) => {
    setTimeout(() => {
      if (shouldFail) {
        resolve({
          ok: false,
          error: 'Không thể kết nối đến máy chủ thư viện. Vui lòng thử lại sau!',
        });
      } else {
        // Trả về bản sao của danh sách sách
        resolve({
          ok: true,
          data: [...INITIAL_BOOKS],
        });
      }
    }, 500);
  });
};
